-- d1-migration: apply-once
-- Add reviewed columns without removing existing tables or readers.
ALTER TABLE amenities ADD COLUMN short_name TEXT;
ALTER TABLE amenities ADD COLUMN short_description TEXT;
ALTER TABLE amenities ADD COLUMN long_description TEXT;
ALTER TABLE amenities ADD COLUMN benefit_headline TEXT;
ALTER TABLE amenities ADD COLUMN benefit_body TEXT;
ALTER TABLE amenities ADD COLUMN slug TEXT;
ALTER TABLE amenities ADD COLUMN type_id TEXT;
ALTER TABLE amenities ADD COLUMN category_id TEXT;
ALTER TABLE amenities ADD COLUMN global_amenity INTEGER CHECK(global_amenity IN (0,1));
ALTER TABLE amenities ADD COLUMN active INTEGER CHECK(active IN (0,1));
ALTER TABLE amenities ADD COLUMN updated_at TEXT;
ALTER TABLE room_types ADD COLUMN full_name TEXT;
ALTER TABLE room_types ADD COLUMN short_name TEXT;
ALTER TABLE room_types ADD COLUMN name_split_2 TEXT;
ALTER TABLE room_types ADD COLUMN short_description TEXT;
ALTER TABLE room_types ADD COLUMN long_description TEXT;
ALTER TABLE room_types ADD COLUMN benefit_statement TEXT;
ALTER TABLE room_types ADD COLUMN building_id TEXT REFERENCES buildings(id);
ALTER TABLE room_types ADD COLUMN square_feet TEXT;
ALTER TABLE room_types ADD COLUMN number_of_bedrooms INTEGER;
ALTER TABLE room_types ADD COLUMN number_of_beds INTEGER;
ALTER TABLE room_types ADD COLUMN is_suite INTEGER;
ALTER TABLE room_types ADD COLUMN is_room INTEGER;
ALTER TABLE room_types ADD COLUMN bed_type_source_id TEXT;
ALTER TABLE room_types ADD COLUMN number_of_units INTEGER;
ALTER TABLE room_types ADD COLUMN component_room INTEGER;
ALTER TABLE room_types ADD COLUMN active INTEGER;
ALTER TABLE room_types ADD COLUMN webflow_policy_ids TEXT;
ALTER TABLE buildings ADD COLUMN subheadline TEXT;
ALTER TABLE buildings ADD COLUMN short_description TEXT;
ALTER TABLE buildings ADD COLUMN long_description TEXT;
ALTER TABLE buildings ADD COLUMN feature_benefits TEXT;
ALTER TABLE buildings ADD COLUMN status TEXT;
ALTER TABLE buildings ADD COLUMN image_media_asset_id TEXT REFERENCES media_assets(id);
CREATE TRIGGER IF NOT EXISTS building_image_same_tenant_insert BEFORE INSERT ON buildings WHEN NEW.image_media_asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM media_assets WHERE id=NEW.image_media_asset_id AND tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'Building image must belong to same tenant'); END;
CREATE TRIGGER IF NOT EXISTS building_image_same_tenant_update BEFORE UPDATE OF image_media_asset_id,tenant_id ON buildings WHEN NEW.image_media_asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM media_assets WHERE id=NEW.image_media_asset_id AND tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'Building image must belong to same tenant'); END;
CREATE TRIGGER IF NOT EXISTS building_image_asset_tenant_update BEFORE UPDATE OF tenant_id ON media_assets WHEN EXISTS (SELECT 1 FROM buildings WHERE image_media_asset_id=OLD.id AND tenant_id<>NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'Building image must belong to same tenant'); END;
UPDATE amenities SET
 short_name=(SELECT e.short_name FROM amenity_editorial e WHERE e.tenant_id=amenities.tenant_id AND e.amenity_id=amenities.id),
 short_description=(SELECT e.short_description FROM amenity_editorial e WHERE e.tenant_id=amenities.tenant_id AND e.amenity_id=amenities.id),
 long_description=(SELECT e.long_description FROM amenity_editorial e WHERE e.tenant_id=amenities.tenant_id AND e.amenity_id=amenities.id),
 active=(SELECT e.active FROM amenity_editorial e WHERE e.tenant_id=amenities.tenant_id AND e.amenity_id=amenities.id),
 updated_at=(SELECT e.updated_at FROM amenity_editorial e WHERE e.tenant_id=amenities.tenant_id AND e.amenity_id=amenities.id);
CREATE TABLE IF NOT EXISTS room_type_reviews (
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,room_type_id TEXT NOT NULL,review TEXT,review_source TEXT,review_url TEXT,review_date TEXT,reviewer_name_or_handle TEXT,
 status TEXT CHECK(status IN ('draft','published','archived')),created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT,
 FOREIGN KEY(tenant_id,room_type_id) REFERENCES room_types(tenant_id,id));
UPDATE buildings SET subheadline='Stay in the Middle of it All.',short_description=NULL,long_description='The Lodge rooms sit directly above the restaurant, bar and fireside gathering spaces—the right choice for guests who want the Cowboy close at hand. Book one room or take over the floor with your people. Either way, you''re never far from dinner, drinks or the fire.
',feature_benefits=NULL,status='published' WHERE id='6abd4ab24a8b01c01798a3cc';
UPDATE buildings SET subheadline='The View Does Most of the Talking.',short_description=NULL,long_description='Perched on Panther Mountain, Mountain View Haus looks across the valley toward the Big Indian Wilderness. Inside, wood beams, a river-stone hearth and a full kitchen give you the familiar pleasure of a proper mountain house. Book two bedrooms or take all four. Then put something on the fire, pour a drink and let the week loosen its grip.
',feature_benefits='Available as 2 or 4 bedrooms · Sleeps up to 8',status='published' WHERE id='6abd3eb0ce8fc8aa2a739e85';
UPDATE buildings SET subheadline='The Easygoing way Into the Catskills.',short_description=NULL,long_description='Set at the trailhead beneath Slide Mountain, these are some of our simplest rooms and our easiest way into Cowboy. Less fuss, fewer frills, and a little more room in the budget for whatever happens next. The trails start outside. Ralph’s is across the street. The rest of Cowboy is just up the hill.
',feature_benefits=NULL,status='published' WHERE id='6abd3e2f353a23ebb2777252';
UPDATE buildings SET subheadline=NULL,short_description=NULL,long_description='Forest House is the quieter side of the Cowboy. Tucked among the pines, these rooms carry more of the old Catskills spirit: warm, familiar and a little nostalgic, with just enough space to settle in without overthinking it. Downstairs, the Day Room and porch are there when you''re ready for company.
',feature_benefits=NULL,status='published' WHERE id='6abd3dd45292f6b4913ed727';
UPDATE buildings SET subheadline='Old Catskills Your Way',short_description=NULL,long_description='Step inside a century-old cabin built for long weekends and people you actually like traveling with. Wood beams, a river-stone hearth and a vaulted living room set the pace downstairs. Four bedrooms give everyone somewhere to disappear upstairs. Cook together. Don''t cook at all. Walk the trails. Sit by the fire. There isn''t much of a schedule here unless you bring one with you.',feature_benefits='Sleeps up to 8 · Available as 2 or 4 bedrooms',status='published' WHERE id='6abd3db631171519bbcfce3c';
UPDATE buildings SET subheadline='The Mountain House Fantasy.',short_description='Our largest standalone suite leans into the property''s Alpine past with wood-paneled cathedral ceilings, big picture windows and a private deck overlooking the landscape. Inside, there''s a full kitchen, breakfast nook, fireplace and enough living space to spread out. Outside, a cedar soaking tub for two. Come for a weekend. Pretend it''s yours.',long_description='Set apart along the forest edge, The Chalet is Cowboy''s largest standalone one-bedroom suite and the closest thing to borrowing your own Alpine mountain house for the weekend. Wood-paneled cathedral ceilings and big picture windows open onto two living areas, a gas fireplace, full kitchen and breakfast nook. The king bedroom is joined by a pull-out sofa, so the space can sleep up to four, while the private deck holds an outdoor cedar soaking tub for two. Private parking keeps the arrival and stay a little more self-contained. Expect real privacy, room to cook and spread out, and a stay that feels more residential than a hotel room.',feature_benefits='Family-friendly · Dog-friendly',status='published' WHERE id='6abd3d80a1c60b5b2b4ec90e';
UPDATE buildings SET subheadline='Quite Literally, Your Cabin in the Woods.',short_description='Six hundred square feet. Your own porch. A copper clawfoot tub. A fireplace. Enough space to settle in and briefly consider never going home. The open-plan interior gives you a king bed, rain shower, leather loveseat and dining table, while the porch puts the Catskills just outside your door. Coffee works out there. Cocktails work better.',long_description='
Completely detached along the forest edge, The Cabin is a 600-square-foot private hideaway with no shared hallway and plenty of room to settle in. The open-plan layout includes a king bed, copper clawfoot soaking tub, walk-in rain shower, gas fireplace, leather loveseat, dining or work table and private covered porch. A twin bunk or lounging nook adds flexibility, while Wright, Pendleton, Printsburgh and the minibar bring the familiar Cowboy details. Despite the standalone setting, the Lodge, sauna, trails, firepits and creekside gathering spaces are still within easy reach. Expect more privacy than a guest room, less space than a full chalet, and the feeling of having a little Catskills cabin to yourselves.',feature_benefits='Family-friendly · Dog-friendly',status='published' WHERE id='6abd3d5731171519bbcf983b';
UPDATE buildings SET subheadline='Bathing Outside Among the Trees',short_description='Walden sits closer to the woods. Its ten cabin-style rooms trade Alpine''s lodge-like romance for something quieter and more elemental: private decks, forest views and, in the bathing suites, cedar tubs made for soaking outside.',long_description='Walden sits closer to the woods. Its ten cabin-style rooms trade Alpine''s lodge-like romance for something quieter and more elemental: private decks, forest views and, in the bathing suites, cedar tubs made for soaking outside. This is where the Cowboy gets a little wilder.',feature_benefits='This is where the Cowboy gets a little wilder.',status='published' WHERE id='6abd3c85d823085f80ebb4d0';
UPDATE buildings SET subheadline='The Iconic Indoor Soak',short_description='Built into the hillside above the Lodge, Alpine is home to ten of the Cowboy''s most iconic rooms. Every suite puts a freestanding clawfoot tub in front of a picture window, with the forest and mountains doing the decorating outside.',long_description='Built into the hillside above the Lodge, Alpine is home to ten of the Cowboy''s most iconic rooms. Every suite puts a freestanding clawfoot tub in front of a picture window, with the forest and mountains doing the decorating outside. This is where you come to soak, slow down and disappear for a while.',feature_benefits='This is where you come to soak, slow down and disappear for a while.',status='published' WHERE id='6abd3c6b94314e57daf2e472';
UPDATE room_types SET full_name='Mountain View Haus',short_name='Mountain View Haus 2 Bedroom Suite',name_split_2='2 Bedroom Suite',short_description='A proper mountain house with valley views, a river-stone hearth and full kitchen, available with two or four bedrooms.',long_description='Perched on Panther Mountain, Mountain View Haus looks across the valley toward the Big Indian Wilderness. Inside, wood beams, a river-stone hearth and a full kitchen give you the familiar pleasure of a proper mountain house.

Book two bedrooms or take all four.

Then put something on the fire, pour a drink and let the week loosen its grip.',benefit_statement='The View Does Most of the Talking',building_id='6abd3eb0ce8fc8aa2a739e85',square_feet=NULL,number_of_bedrooms=2,number_of_beds=2,is_suite=1,is_room=1,bed_type_source_id='e32c370af45cf97de484aba0703cf939',number_of_units=2,component_room=NULL,active=NULL,webflow_policy_ids=NULL WHERE id='6abd50f0e0589519e89a7f10';
UPDATE room_types SET full_name='Opa''s Cabin',short_name='Opa''s Cabin 2 Bedroom Suite',name_split_2='2 Bedroom Suite',short_description='Step inside a century-old cabin built for long weekends and people you actually like traveling with. Wood beams, a river-stone hearth and a vaulted living room set the pace downstairs. Four bedrooms give everyone somewhere to disappear upstairs. Cook together. Don''t cook at all. Walk the trails. Sit by the fire. There isn''t much of a schedule here unless you bring one with you.',long_description='Each two-bedroom half pairs one king bedroom with one queen bedroom, but the layouts are different. The downstairs configuration includes the vaulted living room, river-stone hearth, full kitchen, dining area, front porch, two bedrooms and one shared bathroom. The upstairs configuration consists of two bedrooms, each with its own en-suite bathroom. Both keep you close to the trailhead and river while giving you a more private, old-school Catskills base for the stay.',benefit_statement='Old Catskills, Your Way',building_id='6abd3db631171519bbcfce3c',square_feet='650',number_of_bedrooms=2,number_of_beds=2,is_suite=1,is_room=1,bed_type_source_id='e32c370af45cf97de484aba0703cf939',number_of_units=2,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7","6acb3c6dd423991cbf6a43ec"]' WHERE id='6abd502ef996502133a61ac0';
UPDATE room_types SET full_name='Lodge',short_name='Lodge 2 Bedroom Suite',name_split_2='2 Bedroom Suite',short_description='Two bedrooms plus a generous shared living space make this one for families, old friends and celebrations that deserve more than adjoining hotel rooms. You''ve got a fireplace, wet bar, deck and plenty of room to gather. And when everyone needs a little distance, that''s what the bedrooms are for.',long_description='Set on the second floor directly above the Main Lodge, the Lodge Two-Bedroom pairs one king bedroom with one queen bedroom and a shared full bathroom with walk-in shower. A private deck, hand-carved willow sculpture, Wright mattresses, Pendleton robes and blankets, hand-printed wallpaper and minibar bring the Cowboy character inside. The location is the real advantage: the Dining Room and Parlor Bar are downstairs, with the sauna, trails, Treenet, firepits and creekside bluestone beach just beyond, and Ralph''s Bar & Bowling nearby. Expect a social, convenient stay for families or friends who want to experience the property together without giving up separate bedrooms.
',benefit_statement='Room for Your People. Right in the Middle of It.',building_id='6abd4ab24a8b01c01798a3cc',square_feet='800',number_of_bedrooms=2,number_of_beds=2,is_suite=1,is_room=0,bed_type_source_id='e32c370af45cf97de484aba0703cf939',number_of_units=1,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4ef9a4e38259878f2727';
UPDATE room_types SET full_name='Mountain View Haus',short_name='Mountain View Haus 4 Bedroom Suite',name_split_2='4 Bedroom Suite',short_description='A proper mountain house with valley views, a river-stone hearth and full kitchen, available with two or four bedrooms.',long_description='Perched on Panther Mountain, Mountain View Haus looks across the valley toward the Big Indian Wilderness. Inside, wood beams, a river-stone hearth and a full kitchen give you the familiar pleasure of a proper mountain house. Book two bedrooms or take all four. Then put something on the fire, pour a drink and let the week loosen its grip.',benefit_statement='The View Does Most of the Talking',building_id='6abd3eb0ce8fc8aa2a739e85',square_feet='350-500',number_of_bedrooms=4,number_of_beds=4,is_suite=1,is_room=1,bed_type_source_id=NULL,number_of_units=1,component_room=1,active=NULL,webflow_policy_ids=NULL WHERE id='6abd4a25cd450395156515c6';
UPDATE room_types SET full_name='Slide Mountain',short_name='Slide Mountain Haus',name_split_2='Full Haus',short_description='Set at the trailhead beneath Slide Mountain, these are some of our simplest rooms and our easiest way into Cowboy. Less fuss, fewer frills, and a little more room in the budget for whatever happens next. The trails start outside. Ralph''s is across the street. The rest of Cowboy is just up the hill. Take over the whole Haus for the crew, with the kitchen, living room, porches and beds all to yourselves.',long_description='Take over all of Slide Mountain Haus and the place shifts from simple rooms to a full Upstate house for the crew. The first floor gives you two bedrooms, one shared bathroom, a full kitchen, dining area and living room; upstairs are three Double Queen bedrooms, each with its own en-suite bathroom. Altogether, the Haus has five bedrooms, four bathrooms and eight beds, sleeping up to sixteen, plus two wrap-around porches for spreading out outside. The hiking trailhead is at the door, Ralph''s is across the street and the main resort sits up the hill. Expect plenty of shared space, straightforward mountain-house comfort and the freedom to come and go as a group without coordinating rooms across the property.',benefit_statement='Your Upstate Place. Without Buying an Upstate Place',building_id='6abd3e2f353a23ebb2777252',square_feet='350-500',number_of_bedrooms=NULL,number_of_beds=NULL,is_suite=1,is_room=NULL,bed_type_source_id=NULL,number_of_units=1,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7","6acb3c6dd423991cbf6a43ec"]' WHERE id='6abd4a24eea80f91a64d01d1';
UPDATE room_types SET full_name='Slide Mountain Haus',short_name='Slide Mountain Haus 2 Bedroom Suite',name_split_2='2 Bedroom Suite',short_description='Set at the trailhead beneath Slide Mountain, these are some of our simplest rooms and our easiest way into Cowboy. Less fuss, fewer frills, and a little more room in the budget for whatever happens next. The trails start outside. Ralph''s is across the street. The rest of Cowboy is just up the hill. Two bedrooms plus a kitchen and living room for families, small groups, or anyone who wants more than just a place to sleep.',long_description='On the first floor of Slide Mountain Haus, this two-bedroom suite gives families or small groups a king bedroom, a queen bedroom, one shared bathroom, full kitchen and a proper living room for game nights, coffee or doing very little. The front porch looks toward Slide Mountain, and the trailhead begins right outside. Ralph''s is across the street, while the rest of Cowboy is up the hill. For larger groups, the Double Queen rooms sit directly upstairs and the whole Haus can be booked together. Expect one of the property''s most practical group setups: more space and independence than a guest room, with a simpler finish and easier price point than the larger private houses.',benefit_statement='A Little More Room to Spread Out',building_id='6abd3e2f353a23ebb2777252',square_feet='600',number_of_bedrooms=2,number_of_beds=2,is_suite=1,is_room=0,bed_type_source_id='e32c370af45cf97de484aba0703cf939',number_of_units=NULL,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a24b799b47be46fb0e7';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a24b799b47be46fb0e7',tenant_id,id,'Stayed in one of the 2 bedroom options. Clean, decor warm and cozy, beds comfortable, kitchen well equipped... Food was delicious though.','113fb7dac1bc4b2334b4b432eb80383a','https://travelswap.xyz/hotel/urban-cowboy-lodge-42566439#reviews','2026-02-18T00:00:00.000Z','Sarine' FROM room_types WHERE id='6abd4a24b799b47be46fb0e7';
UPDATE room_types SET full_name='Slide Mountain',short_name='Slide Mountain Double Queen',name_split_2='Double Queen',short_description='Two queen beds, porch access and an easy setup for friends sharing a Catskills weekend.',long_description='Set at the trailhead beneath Slide Mountain, these are some of our simplest rooms and our easiest way into Cowboy. Less fuss, fewer frills, and a little more room in the budget for whatever happens next.

The trails start outside. Ralph''s is across the street. The rest of Cowboy is just up the hill.

Two queen beds, porch access and an easy setup for friends sharing a Catskills weekend.',benefit_statement='Simple, Flexible, Friend-Ready',building_id='6abd3e2f353a23ebb2777252',square_feet='320',number_of_bedrooms=NULL,number_of_beds=NULL,is_suite=NULL,is_room=1,bed_type_source_id='88dcc8fa3677123856ae63a96e70f527',number_of_units=NULL,component_room=NULL,active=1,webflow_policy_ids=NULL WHERE id='6abd4a23f555b2ce3cc49edc';
UPDATE room_types SET full_name='Lodge ',short_name='Lodge King Room',name_split_2='King Room',short_description='A comfortable King room directly above the heart of the Cowboy. Dinner downstairs. Drinks around the corner. The sauna and trails just beyond the front door. When you want the action close and your room simple, this is your spot.',long_description='On the second floor directly above the Dining Room, Parlor Bar and fireside gathering spaces, the Lodge King keeps you closest to the social heart of Cowboy. The room itself is straightforward: one king bed, table and chairs, walk-in shower, hand-carved willow artwork, Wright mattress, Pendleton layers, Printsburgh wallpaper and stocked minibar. What you are really choosing is location. Expect dinner, drinks, sauna and trails to be steps away, with more of the Lodge''s energy around you than you would find in Alpine, Walden or the standalone houses.
',benefit_statement='The Easiest Way Into Lodge Life',building_id='6abd4ab24a8b01c01798a3cc',square_feet='220 – 300',number_of_bedrooms=0,number_of_beds=1,is_suite=NULL,is_room=1,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=NULL,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7","6acb3c6dd423991cbf6a43ec"]' WHERE id='6abd4a22b6febadd9de10f2b';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a22b6febadd9de10f2b',tenant_id,id,'Reviews the entry key right above the main lodge with custom hand-printed wallpaper, willow sculpture, Wright mattress, and easy access to the sauna and bar.','113fb7dac1bc4b2334b4b432eb80383a','https://travelswap.xyz/hotel/urban-cowboy-lodge-42566439#reviews','2025-11-03T00:00:00.000Z','AnDrew' FROM room_types WHERE id='6abd4a22b6febadd9de10f2b';
UPDATE room_types SET full_name='Lodge',short_name='Lodge 3 Bedroom Suite',name_split_2='3 Bedroom Suite',short_description='Three bedrooms plus a generous shared living space make this one for families, old friends and celebrations that deserve more than adjoining hotel rooms. You''ve got a fireplace, wet bar, deck and plenty of room to gather. And when everyone needs a little distance, that''s what the bedrooms are for.',long_description='Also on the second floor of the Main Lodge, the Three-Bedroom Suite combines the Lodge Penthouse with two additional private rooms, creating one of the property''s most expansive setups for a group. Two king beds and one queen bed connect to a grand shared living room with wet bar, fireplace, private deck and some of the Lodge''s most dramatic views, plus shared full bathrooms and a copper clawfoot soaking tub. The restaurant, Parlor Bar and fireside gathering spaces are directly downstairs, so the suite works especially well for families, friends and celebrations that want the social side of Cowboy ',benefit_statement='Bring Your People',building_id='6abd4ab24a8b01c01798a3cc',square_feet='1600',number_of_bedrooms=3,number_of_beds=3,is_suite=1,is_room=NULL,bed_type_source_id=NULL,number_of_units=1,component_room=1,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a22d0f78074502c9047';
UPDATE room_types SET full_name='Lodge',short_name='Lodge Penthouse',name_split_2='Penthouse',short_description='The biggest single room in the Lodge gives you a bedroom, living room, private deck and some of the property''s most dramatic views. The handcrafted black-willow headboard turns the bedroom into its own little forest. The copper clawfoot tub makes a strong argument for staying there. Your private living room and wet bar handle the rest.',long_description='At the top of the Main Lodge, the Penthouse is the largest single accommodation in the building, with roughly 1,000 square feet dedicated to one bedroom and a substantial private living room. Floor-to-ceiling vaulted windows bring in the mountain views, while a wet bar, dining table and furnished deck give you space to settle in beyond the bedroom. The king bedroom is anchored by Cowboy''s hand-crafted black-willow headboard, and the master bath adds a copper clawfoot tub and double-headed rain shower. The Dining Room, Parlor Bar, fireside Parlor and Den are downstairs, while larger groups can combine the Penthouse with two additional Lodge rooms to create the Three-Bedroom Suite. Expect a more expansive, romantic version of Lodge life, with the social heart of the property below and enough private space upstairs to make staying in equally appealing.
',benefit_statement='The Honeymoon Suite. Officially Unofficial',building_id='6abd4ab24a8b01c01798a3cc',square_feet='1,000',number_of_bedrooms=1,number_of_beds=1,is_suite=1,is_room=NULL,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=1,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a215ef0918ac0281f5b';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a215ef0918ac0281f5b',tenant_id,id,'If you want a boutique hotel that feels like a whole mood, this is it. The interiors lean rustic + eclectic in a way that feels intentional and fun, not themed. And yes, the cedar soaking tubs are as dreamy as they sound. Swoon is the correct reaction.','0d66b4fe1267d358efc7e722eab089c5','https://www.lemon8-app.com/experience/best-boutique-hotels-upstate-new-york','2026-05-12T00:00:00.000Z','@tavernatravels' FROM room_types WHERE id='6abd4a215ef0918ac0281f5b';
UPDATE room_types SET full_name='Forest House',short_name='Forest House King',name_split_2='King Room',short_description='More room to stretch out, plus a private balcony with the forest at eye level. Take your coffee outside. Take your time coming back in.',long_description='Upstairs in Forest House, the King rooms add a little more room and a private balcony looking into the trees. Inside you''ll find a king bed, extra seating, en-suite walk-in shower, Wright mattress, Pendleton layers, Printsburgh wallpaper and minibar, with access to the shared Day Room downstairs. Expect the same nostalgic, quieter Forest House character as the Queen rooms, but with a more private perch and forest at eye level. It is a good middle ground for guests who want more breathing room without moving into one of the larger cabins or chalets.
',benefit_statement='Wake Up in the Treetops',building_id='6abd3dd45292f6b4913ed727',square_feet='220 – 300',number_of_bedrooms=0,number_of_beds=1,is_suite=NULL,is_room=1,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=NULL,component_room=NULL,active=1,webflow_policy_ids=NULL WHERE id='6abd4a214da3116bfbdd9a40';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a214da3116bfbdd9a40',tenant_id,id,NULL,NULL,'https://travelswap.xyz/hotel/urban-cowboy-lodge-42566439#reviews','2025-12-02T00:00:00.000Z','Jake' FROM room_types WHERE id='6abd4a214da3116bfbdd9a40';
UPDATE room_types SET full_name='Forest House',short_name='Forest House Queen',name_split_2='Qeen Room',short_description='Cozy, charming and heavy on old-school mountain character, the Queen feels a little like someplace you remember—even if you''ve never been here before. A good room for sleeping late, reading something you actually finish and disappearing into the woods for most of the day.',long_description='Forest House sits among the pines and feels more like old Catskills guesthouse living than the property''s bathing-suite buildings. The Queen rooms give you two queen beds, an en-suite walk-in shower and the full Cowboy layer of Wright mattresses, Pendleton robes and blankets, Printsburgh wallpaper and minibar, with plenty of true Borscht Belt charm. Downstairs, the shared Day Room and card table give you somewhere to make friends, while the front porch is there for reading, coffee or doing very little. Expect a simpler, more nostalgic stay with less emphasis on private in-room experiences and more on using the house as a comfortable base for the rest of the property.',benefit_statement='Small Room. Big Catskills Energy',building_id='6abd3dd45292f6b4913ed727',square_feet='220 – 300',number_of_bedrooms=0,number_of_beds=1,is_suite=NULL,is_room=1,bed_type_source_id='dcf29f6638b39f418ea1eed3b86ecc91',number_of_units=2,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7","6acb3c6dd423991cbf6a43ec"]' WHERE id='6abd4a209dd47278e0fd475d';
UPDATE room_types SET full_name='Opa''s Cabin',short_name='Opa''s Cabin ',name_split_2='4 Bedroom Suite',short_description='Step inside a century-old cabin built for long weekends and people you actually like traveling with. Wood beams, a river-stone hearth and a vaulted living room set the pace downstairs. Cook together. Don''t cook at all. Walk the trails. Sit by the fire. There isn''t much of a schedule here unless you bring one with you. ',long_description='Four bedrooms give everyone somewhere to disappear upstairs and includes the entire century-old cabin under one reservation. Downstairs, the vaulted living room, river-stone hearth, full kitchen, dining area and front porch create the shared heart of the house alongside one king bedroom, one queen bedroom and a shared bathroom. Upstairs adds another king bedroom and queen bedroom, each with its own en-suite bathroom. Expect four bedrooms, three bathrooms, plenty of room to gather and direct access to the trails and river without sharing the house with another party.',benefit_statement='Old Catskills, Your Way',building_id='6abd3db631171519bbcfce3c',square_feet='1200',number_of_bedrooms=4,number_of_beds=4,is_suite=1,is_room=1,bed_type_source_id='e32c370af45cf97de484aba0703cf939',number_of_units=1,component_room=1,active=1,webflow_policy_ids=NULL WHERE id='6abd4a20d0f78074502c8fb7';
UPDATE room_types SET full_name='The Chalet',short_name='The Chalet',name_split_2=NULL,short_description='Our largest standalone suite leans into the property''s Alpine past with wood-paneled cathedral ceilings, big picture windows and a private deck overlooking the landscape. Inside, there''s a full kitchen, breakfast nook, fireplace and enough living space to spread out. Outside, a cedar soaking tub for two. Come for a weekend. Pretend it''s yours.',long_description='Set apart along the forest edge, The Chalet is Cowboy''s largest standalone one-bedroom suite and the closest thing to borrowing your own Alpine mountain house for the weekend. Wood-paneled cathedral ceilings and big picture windows open onto two living areas, a gas fireplace, full kitchen and breakfast nook. The king bedroom is joined by a pull-out sofa, so the space can sleep up to four, while the private deck holds an outdoor cedar soaking tub for two. Private parking keeps the arrival and stay a little more self-contained. Expect real privacy, room to cook and spread out, and a stay that feels more residential than a hotel room.
',benefit_statement='The Mountain-House Fantasy',building_id='6abd3d80a1c60b5b2b4ec90e',square_feet='700',number_of_bedrooms=1,number_of_beds=2,is_suite=1,is_room=NULL,bed_type_source_id='e32c370af45cf97de484aba0703cf939',number_of_units=1,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7","6acb3c6dd423991cbf6a43ec"]' WHERE id='6abd4a1f9b8749a160b00989';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a1f9b8749a160b00989',tenant_id,id,'Highlights the cathedral ceilings, picture windows, two lounge areas, gas fireplace, full kitchen, breakfast nook, and private deck with outdoor cedar soaking tub.','0d66b4fe1267d358efc7e722eab089c5',NULL,NULL,'Field Mag / Urban Cowboy Guide' FROM room_types WHERE id='6abd4a1f9b8749a160b00989';
UPDATE room_types SET full_name='The Cabin',short_name='The Cabin',name_split_2=NULL,short_description='Six hundred square feet. Your own porch. A copper clawfoot tub. A fireplace. Enough space to settle in and briefly consider never going home. The open-plan interior gives you a king bed, rain shower, leather loveseat and dining table, while the porch puts the Catskills just outside your door. Coffee works out there. Cocktails work better.',long_description='Completely detached along the forest edge, The Cabin is a 600-square-foot private hideaway with no shared hallway and plenty of room to settle in. The open-plan layout includes a king bed, copper clawfoot soaking tub, walk-in rain shower, gas fireplace, leather loveseat, dining or work table and private covered porch. A twin bunk or lounging nook adds flexibility, while Wright, Pendleton, Printsburgh and the minibar bring the familiar Cowboy details. Despite the standalone setting, the Lodge, sauna, trails, firepits and creekside gathering spaces are still within easy reach. Expect more privacy than a guest room, less space than a full chalet, and the feeling of having a little Catskills cabin to yourselves.',benefit_statement='Quite Literally, Your Cabin in the Woods',building_id='6abd3d5731171519bbcf983b',square_feet='600',number_of_bedrooms=1,number_of_beds=2,is_suite=NULL,is_room=1,bed_type_source_id='3a9325f54b03c6e962fde831580dd421',number_of_units=1,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a1fd0f78074502c8f17';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a1fd0f78074502c8f17',tenant_id,id,'We stayed in The Cabin, a 600-square-foot, open concept suite with what I can only describe as a king-sized cloud nine for sleeping on... Spread out under the wood-paneled, vaulted ceilings and chandelier, there''s a table and chairs for eating and working, a comfy leather couch for lounging, a cast iron stove to keep you warm on cold nights, and a hammered copper clawfoot tub.','0d66b4fe1267d358efc7e722eab089c5','https://www.betches.com/article/lifestyle/scribners-lodge-urban-cowboy-catskills-review-291660-20240215','2024-02-16T00:00:00.000Z','Katie CorvinoKatie CorvinoKatie Corvino' FROM room_types WHERE id='6abd4a1fd0f78074502c8f17';
UPDATE room_types SET full_name='Walden',short_name='Walden King',name_split_2='King Room',short_description='Simple, warm and tucked into the woods, the Walden King is for guests who want the forest outside and just enough Cowboy inside. Take your coffee to the deck. Write something at the desk. Wander off for the day. Or don''t.',long_description='Walden King is the simplest way to stay on the wooded, creekside side of the property. These adults-only rooms sit downhill along Esopus Creek and include a king bed, private deck with forest views, letter-writing desk and walk-in shower, plus a Wright mattress, Pendleton layers, Printsburgh wallpaper, minibar and Wi-Fi. The sauna, trails and creekside bluestone beach are close at hand, while the Lodge and its dining and bar spaces sit farther up the property. There is no soaking tub in this room type, which is exactly why it works for guests who want Walden''s quiet, cabin-like setting without the bathing-suite experience. Expect a warm, straightforward room with the forest doing most of the heavy lifting.',benefit_statement='Your Cabin-Era Begins Here',building_id='6abd3c85d823085f80ebb4d0',square_feet='300',number_of_bedrooms=0,number_of_beds=1,is_suite=NULL,is_room=1,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=2,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d","6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a1ee1a11fa225d6b50c';
UPDATE room_types SET full_name='Walden Sunrise ',short_name='Walden Sunrise Bathing Suite',name_split_2='Bathing Suite',short_description='Some of the best sunrise views on the property belong to this room. Watch the first light arrive through the diamond-shaped window or, better yet, from the cedar soaking tub on your private porch. Two leather loungers inside give you somewhere to do very little afterward.',long_description='Downhill in Walden, the Sunrise suites are angled toward the morning light. A diamond-shaped window catches the first light, while a private deck with cedar soaking tub lets you take it outside. Inside are a king bed, two leather loungers, letter-writing desk, walk-in shower, Pendleton layers, hand-printed wallpaper and the usual Cowboy comforts. Expect a little more square footage than standard Walden rooms, some of the property''s strongest sunrise views and an adults-only setting where morning coffee and a long soak can easily become the day''s first plan.
',benefit_statement='For Morning People. And People Who Might Become Morning People.',building_id='6abd3c85d823085f80ebb4d0',square_feet='400',number_of_bedrooms=NULL,number_of_beds=NULL,is_suite=1,is_room=NULL,bed_type_source_id=NULL,number_of_units=NULL,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d","6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a1d2bf84a273d30378a';
UPDATE room_types SET full_name='Walden Forest',short_name='Walden Forest Bathing Suite with Den',name_split_2='Bathing Suite with Den',short_description='Walden''s largest suite gives you more room inside and your own cedar soaking tub outside. Start slow in the lounge. Take the afternoon to the deck. Stay in the water until the stars come out. There is, technically, a desk too. We prefer the original purpose: writing letters to your lover.',long_description='Walden''s largest suite style, set downhill by Esopus Creek, this room pairs a king bed with an indoor den and lounge, a letter-writing desk and a private deck with a cedar soaking tub. The extra living space makes it a good choice for guests who want the outdoor bathing ritual without spending every indoor hour on the bed. Inside you''ll find the same Pendleton layers, hand-printed wallpaper, Wright mattress and walk-in shower as the rest of Walden. Expect a quiet, adults-only stay surrounded by trees, with more room to settle in and nowhere you need to rush off to.
',benefit_statement='Stay in the Trees a Little Longer',building_id='6abd3c85d823085f80ebb4d0',square_feet='450',number_of_bedrooms=1,number_of_beds=1,is_suite=1,is_room=NULL,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=NULL,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d"]' WHERE id='6abd4a1debcab0ea7e461c9a';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a1debcab0ea7e461c9a',tenant_id,id,'Highlights Walden''s largest suite with custom lounge area, private deck, and outdoor heated cedar Japanese soaking tub under the stars.',NULL,NULL,NULL,NULL FROM room_types WHERE id='6abd4a1debcab0ea7e461c9a';
UPDATE room_types SET full_name='Walden Forest',short_name='Walden Forest Bathing Suite',name_split_2='Bathing Suite',short_description='Step onto your private deck, climb into a cedar soaking tub and listen to absolutely nothing happening in the woods. Inside, hand-printed wallpaper, Old Hickory furniture, Pendleton layers and a king bed keep things warm. Outside, the forest handles the rest.',long_description='Also downhill in Walden, the Sunrise suites are angled toward the morning light. A diamond-shaped window catches the first light, while a private deck with cedar soaking tub lets you take it outside. Inside are a king bed, two leather loungers, letter-writing desk, walk-in shower, Pendleton layers, hand-printed wallpaper and the usual Cowboy comforts. Expect a little more square footage than standard Walden rooms, some of the property''s strongest sunrise views and an adults-only setting where morning coffee and a long soak can easily become the day''s first plan.
',benefit_statement='Soak Where Open Sky and Forest Meet',building_id='6abd3c85d823085f80ebb4d0',square_feet='350 – 500',number_of_bedrooms=1,number_of_beds=1,is_suite=1,is_room=NULL,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=4,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d","6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a1a4a8b01c0179853c1';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a1a4a8b01c0179853c1',tenant_id,id,'Forest bathing suites feature outdoor heated cedar Japanese soaking tubs for two — ideal for watching snow filter through the fir trees on a late winter evening... Hand-painted wallpaper stretches from the baseboard across the ceiling, echoing the Native American-inspired motifs of the wool Pendleton bedspreads and bathrobes.','0d66b4fe1267d358efc7e722eab089c5','https://thepointsguy.com/news/urban-cowboy-catskills-first-look/','2020-06-06T00:00:00.000Z','The Points Guy' FROM room_types WHERE id='6abd4a1a4a8b01c0179853c1';
UPDATE room_types SET full_name='Alpine Penthouse',short_name='Alpine Penthouse Bathing Suite',name_split_2='Bathing Suite',short_description='Tucked beneath the eaves at the top of Alpine, these are the building''s biggest and most playful suites—dormered ceilings, exposed beams, unexpected angles and a balcony made for two. There''s a copper clawfoot tub, naturally. And a fireplace for everything that comes after.Tucked beneath the eaves at the top of Alpine, these are the building''s biggest and most playful suites—dormered ceilings, exposed beams, unexpected angles and a balcony made for two. There''s a copper clawfoot tub, naturally. And a fireplace for everything that comes after.',long_description='These third-floor suites sit beneath Alpine''s eaves, directly behind and uphill from the Main Lodge. They are the largest of the Alpine suites, with dormered ceilings, exposed beams and unusual angles that make them feel more like little mountain apartments than standard hotel rooms, while a private balcony for two looks toward Panther Mountain. Inside you''ll find a king bed, copper clawfoot soaking tub, gas fireplace, leather loveseat, heated bathroom floors and walk-in shower. Expect an adults-only stay with more space, more architectural character and a quieter perch above the rest of Alpine.',benefit_statement='Up Where the Rooftops Meet the Mountain',building_id='6abd3c6b94314e57daf2e472',square_feet='500',number_of_bedrooms=1,number_of_beds=1,is_suite=1,is_room=NULL,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=2,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d","6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a19b81d023e2f3d1138';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a19b81d023e2f3d1138',tenant_id,id,'Notes the 3rd-floor penthouse layout with dormered ceilings, exposed beams, built-in gas fireplace, copper clawfoot tub, leather loveseat, and elevated balcony built for two.','0d66b4fe1267d358efc7e722eab089c5',NULL,'2025-12-27T00:00:00.000Z','Secret NYC / Fathom Away' FROM room_types WHERE id='6abd4a19b81d023e2f3d1138';
UPDATE room_types SET full_name='Alpine',short_name='Alpine Bathing Suite with Den',name_split_2='Bathing Suite with Den',short_description='There''s only one like this. Stretch out in the built-in chaise den by the fire, or climb into the copper clawfoot tub and take in one of Alpine''s best mountain views. It''s part bathing suite, part hideaway, and exactly the kind of room that makes leaving for dinner feel optional.',long_description='Room 18 is Alpine''s one-of-one Bathing Suite with Den, perched on the hillside directly behind the Main Lodge. Along with the king bed and copper clawfoot soaking tub, you get a built-in chaise den beside a roaring cast-iron stove, with one of Alpine''s strongest mountain views visible from both the lounge and the tub. A private deck extends that view outside. Heated bathroom floors, a walk-in shower, Wright mattress, Pendleton layers, hand-printed wallpaper and minibar round out the room. Expect the signature indoor bathing experience with a little more space to lounge, read or simply disappear between soaks.
',benefit_statement='A Little More Room to Disappear',building_id='6abd3c6b94314e57daf2e472',square_feet='450',number_of_bedrooms=1,number_of_beds=1,is_suite=1,is_room=NULL,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=1,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d","6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd4a18f2574f2ecab86e33';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd4a18f2574f2ecab86e33',tenant_id,id,'What a wonderful experience! From the moment you walked thru the door you were greeted with a welcome drink. The staff was friendly and tentative. My partner and I were celebrating our anniversary and then sent us a complimentary bottle of champagne to the room. There was so much to do around the property but the soaking tub in the room was my favorite part. Looking forward to staying again in the summer time to see all the trails and outdoor activities. 10/10! Thank you so much','113fb7dac1bc4b2334b4b432eb80383a','https://travelswap.xyz/hotel/urban-cowboy-lodge-42566439#reviews','2026-02-09T00:00:00.000Z','Tiffany' FROM room_types WHERE id='6abd4a18f2574f2ecab86e33';
UPDATE room_types SET full_name=' Alpine',short_name=' Alpine Bathing Suite',name_split_2='Bathing Suite',short_description='This is classic Urban Cowboy: a clawfoot tub by the window, a fire nearby and your own deck looking out into the woods. Fill the tub. Put on a robe. Watch the mountain change with the light. Dinner can wait a minute. Signature details include a king bed, cast-iron stove, private deck, heated bathroom floors, hand-printed wallpaper and walk-in shower.',long_description='Perched on the hillside directly behind the Main Lodge, the Alpine Bathing Suites are the classic indoor-soak version of Cowboy. Each adults-only room pairs a king bed with a freestanding clawfoot tub set beside a picture window, a cast-iron wood stove and a private deck with rocking chairs. Heated bathroom floors and a walk-in shower make cold mountain mornings easier, while Wright mattresses, Pendleton layers, Printsburgh wallpaper and a stocked minibar bring the rest of the room together. Expect the Lodge to be close, the hillside to feel quiet and the tub to become part of the day''s itinerary.',benefit_statement='The Iconic Soak',building_id='6abd3c6b94314e57daf2e472',square_feet='350',number_of_bedrooms=1,number_of_beds=1,is_suite=1,is_room=NULL,bed_type_source_id='4a1795ffb5ce99db12f83346b8fa5298',number_of_units=7,component_room=NULL,active=1,webflow_policy_ids='["6abc8c9c09f60a24832b181d","6abc8c9ca5f47abed271d0f7"]' WHERE id='6abd3f70ebcab0ea7e3e68a5';
INSERT OR IGNORE INTO room_type_reviews(id,tenant_id,room_type_id,review,review_source,review_url,review_date,reviewer_name_or_handle) SELECT 'webflow-room-review:6abd3f70ebcab0ea7e3e68a5',tenant_id,id,'I checked into my Alpine Bathing Suite, one of eight in the dual-level cabin uphill from the main lodge... A well-worn leather chair was perfectly positioned in front of the warming potbelly stove. The clawfoot tub glistened as the centerpiece of the room. The large outdoor deck was fitted with wooden rocking chairs and a view of the mountains. Yes, we could settle in here.','0d66b4fe1267d358efc7e722eab089c5','https://fathomaway.com/urban-cowboy-lodge-review-catskills-new-york/','2020-07-01T00:00:00.000Z','California Chaney' FROM room_types WHERE id='6abd3f70ebcab0ea7e3e68a5';
